package lk.sunshine.smartcare.features.doctor;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import java.time.*;
import java.util.*;

@Repository
public class DoctorRepository {
 private final JdbcTemplate db; public DoctorRepository(JdbcTemplate db){this.db=db;}
 public List<Map<String,Object>> specialties(){return db.queryForList("SELECT id,name FROM specialty ORDER BY name");}
 public long createSpecialty(String n){return db.queryForObject("INSERT INTO specialty(name) OUTPUT INSERTED.id VALUES(?)",Long.class,n);}
 public int deleteSpecialty(long id){return db.update("DELETE FROM specialty WHERE id=? AND NOT EXISTS(SELECT 1 FROM doctor WHERE specialty_id=?)",id,id);}
 public int specialtyExists(long id){return db.queryForObject("SELECT COUNT(*) FROM specialty WHERE id=?",Integer.class,id);}
 public int specialtyCount(String n){return db.queryForObject("SELECT COUNT(*) FROM specialty WHERE LOWER(name)=LOWER(?)",Integer.class,n);}
 public String userRole(long id){return db.query("SELECT role FROM app_user WHERE id=?",(r,n)->r.getString(1),id).stream().findFirst().orElse(null);}
 public int linkedDoctorCount(long id){return db.queryForObject("SELECT COUNT(*) FROM doctor WHERE user_id=?",Integer.class,id);}
 public int emailCount(String e){return db.queryForObject("SELECT COUNT(*) FROM app_user WHERE email=?",Integer.class,e);}
 public int emailCountExcept(String e,long userId){return db.queryForObject("SELECT COUNT(*) FROM app_user WHERE email=? AND id<>?",Integer.class,e,userId);}
 public int registrationCount(String r,Long x){return db.queryForObject("SELECT COUNT(*) FROM doctor WHERE registration_id=? AND (? IS NULL OR id<>?)",Integer.class,r,x,x);}
 public long createDoctorUser(String e,String p,String n){return db.queryForObject("INSERT INTO app_user(email,password_hash,role,full_name) OUTPUT INSERTED.id VALUES(?,?,'DOCTOR',?)",Long.class,e,p,n);}
 public List<Map<String,Object>> doctors(String sp,Long branch){return db.queryForList("SELECT d.id,d.display_name AS full_name,s.name AS specialty,d.department,a.today_open_slots,a.next_available_today,f.average_rating,f.review_count FROM doctor d JOIN specialty s ON s.id=d.specialty_id OUTER APPLY(SELECT COUNT(*) today_open_slots,MIN(sl.starts_at) next_available_today FROM slot sl WHERE sl.doctor_id=d.id AND (? IS NULL OR sl.branch_id=?) AND sl.status='AVAILABLE' AND sl.starts_at>=SYSDATETIME() AND sl.starts_at<DATEADD(day,1,CAST(SYSDATETIME() AS date)))a OUTER APPLY(SELECT CAST(AVG(CAST(r.rating AS DECIMAL(4,2))) AS DECIMAL(3,1)) average_rating,COUNT(*) review_count FROM appointment_review r JOIN appointment ap ON ap.id=r.appointment_id JOIN slot sl ON sl.id=ap.slot_id WHERE sl.doctor_id=d.id AND r.deleted_at IS NULL)f WHERE d.active=1 AND (?='' OR LOWER(s.name) LIKE LOWER(?)) AND EXISTS(SELECT 1 FROM doctor_branch db JOIN branch b ON b.id=db.branch_id WHERE db.doctor_id=d.id AND db.active=1 AND b.active=1 AND (? IS NULL OR db.branch_id=?)) ORDER BY CASE WHEN a.today_open_slots>0 THEN 0 ELSE 1 END,d.display_name",branch,branch,sp,"%"+sp+"%",branch,branch);}
 public List<Map<String,Object>> allForAdmin(String sp){return db.queryForList("SELECT d.id,d.user_id,d.display_name AS full_name,u.email,d.registration_id,d.specialty_id,s.name AS specialty,d.department,d.active FROM doctor d LEFT JOIN app_user u ON u.id=d.user_id JOIN specialty s ON s.id=d.specialty_id WHERE (?='' OR LOWER(s.name) LIKE LOWER(?)) ORDER BY d.display_name",sp,"%"+sp+"%");}
 public List<Map<String,Object>> branches(long id){return db.queryForList("SELECT db.branch_id,b.name branch_name,db.room,db.fee,db.active FROM doctor_branch db JOIN branch b ON b.id=db.branch_id WHERE db.doctor_id=? ORDER BY b.name",id);}
 public Map<String,Object> branchAssignment(long d,long b){return db.queryForMap("SELECT db.branch_id,b.name branch_name,db.room,db.fee,db.active FROM doctor_branch db JOIN branch b ON b.id=db.branch_id WHERE db.doctor_id=? AND db.branch_id=?",d,b);}
 public int activeBranchAssignment(long d,long b){return db.queryForObject("SELECT COUNT(*) FROM doctor_branch db JOIN branch br ON br.id=db.branch_id WHERE db.doctor_id=? AND db.branch_id=? AND db.active=1 AND br.active=1",Integer.class,d,b);}
 public void upsertBranch(long d,long b,String r,double f){db.update("MERGE doctor_branch t USING(SELECT ? doctor_id,? branch_id)s ON t.doctor_id=s.doctor_id AND t.branch_id=s.branch_id WHEN MATCHED THEN UPDATE SET room=?,fee=?,active=1 WHEN NOT MATCHED THEN INSERT(doctor_id,branch_id,room,fee) VALUES(s.doctor_id,s.branch_id,?,?);",d,b,r,f,r,f);}
 public void updateBranchRoom(long d,long b,String r){db.update("UPDATE doctor_branch SET room=? WHERE doctor_id=? AND branch_id=?",r,d,b);}
 public int futureBookedAtBranch(long d,long b){return db.queryForObject("SELECT COUNT(*) FROM slot WHERE doctor_id=? AND branch_id=? AND starts_at>SYSDATETIME() AND status='BOOKED'",Integer.class,d,b);}
 public void retireBranch(long d,long b){db.update("UPDATE slot SET retired=1,status='BLOCKED' WHERE doctor_id=? AND branch_id=? AND starts_at>SYSDATETIME() AND status='AVAILABLE'",d,b);db.update("UPDATE schedule_template SET active=0 WHERE doctor_id=? AND branch_id=?",d,b);db.update("DELETE FROM doctor_branch WHERE doctor_id=? AND branch_id=?",d,b);}
 public void deleteBranches(long d){db.update("DELETE FROM doctor_branch WHERE doctor_id=?",d);}
 public List<Map<String,Object>> slots(long d,Long b){return db.queryForList("SELECT sl.id,sl.starts_at,sl.ends_at,sl.branch_id,br.name branch_name,db.room,db.fee FROM slot sl JOIN doctor d ON d.id=sl.doctor_id JOIN branch br ON br.id=sl.branch_id JOIN doctor_branch db ON db.doctor_id=sl.doctor_id AND db.branch_id=sl.branch_id WHERE d.active=1 AND sl.doctor_id=? AND (? IS NULL OR sl.branch_id=?) AND sl.status='AVAILABLE' AND sl.starts_at>=SYSDATETIME() AND db.active=1 AND br.active=1 ORDER BY sl.starts_at",d,b,b);}
 public List<Map<String,Object>> schedules(long d){return db.queryForList("SELECT st.id,st.schedule_date,st.start_time,st.end_time,st.slot_minutes,st.capacity,st.active,st.branch_id,b.name branch_name FROM schedule_template st JOIN branch b ON b.id=st.branch_id WHERE st.doctor_id=? AND st.schedule_date IS NOT NULL ORDER BY st.schedule_date,st.start_time",d);}
 public List<Map<String,Object>> leaves(long d){return db.queryForList("SELECT id,leave_date,reason FROM doctor_leave WHERE doctor_id=? AND leave_date>=CAST(SYSDATETIME() AS date) ORDER BY leave_date",d);}
 public int leaveCount(long d,LocalDate date){return db.queryForObject("SELECT COUNT(*) FROM doctor_leave WHERE doctor_id=? AND leave_date=?",Integer.class,d,date);}
 public long addLeave(long d,LocalDate date,String r){return db.queryForObject("INSERT INTO doctor_leave(doctor_id,leave_date,reason) OUTPUT INSERTED.id VALUES(?,?,?)",Long.class,d,date,r);}
 public int retireOpenSlotsOnDate(long d,LocalDate date){return db.update("UPDATE slot SET status='BLOCKED',retired=1 WHERE doctor_id=? AND CAST(starts_at AS date)=? AND status='AVAILABLE'",d,date);}
 public int bookedOnDate(long d,LocalDate date){return db.queryForObject("SELECT COUNT(*) FROM slot WITH(UPDLOCK,HOLDLOCK) WHERE doctor_id=? AND CAST(starts_at AS date)=? AND status='BOOKED'",Integer.class,d,date);}
 public int deleteLeave(long d,long id){return db.update("DELETE FROM doctor_leave WHERE doctor_id=? AND id=? AND leave_date>=CAST(SYSDATETIME() AS date)",d,id);}
 public Map<String,Object> schedule(long d,long id){return db.queryForMap("SELECT id,schedule_date,start_time,end_time,slot_minutes,capacity,active,branch_id FROM schedule_template WHERE doctor_id=? AND id=? AND schedule_date IS NOT NULL",d,id);}
 public long createDoctor(Long u,String n,String r,long s,String dep){return db.queryForObject("INSERT INTO doctor(user_id,display_name,registration_id,specialty_id,department) OUTPUT INSERTED.id VALUES(?,?,?,?,?)",Long.class,u,n,r,s,dep);}
 public void updateDoctor(long id,String n,long s,String dep,boolean a){db.update("UPDATE doctor SET display_name=?,specialty_id=?,department=?,active=? WHERE id=?",n,s,dep,a,id);}
 public void updateDoctorAccount(long userId,String n,String email){db.update("UPDATE app_user SET full_name=?,email=? WHERE id=?",n,email,userId);}
 public void deleteInactiveSchedules(long doctorId){db.update("DELETE FROM schedule_template WHERE doctor_id=? AND active=0",doctorId);}
 public void deleteRetiredUnbookedSlots(long doctorId){db.update("DELETE sl FROM slot sl WHERE sl.doctor_id=? AND sl.retired=1 AND sl.status<>'BOOKED' AND NOT EXISTS(SELECT 1 FROM appointment a WHERE a.slot_id=sl.id)",doctorId);}
 public int dependencyCount(long id){return db.queryForObject("SELECT(SELECT COUNT(*) FROM schedule_template WHERE doctor_id=? AND active=1)+(SELECT COUNT(*) FROM slot WHERE doctor_id=?)+(SELECT COUNT(*) FROM doctor_leave WHERE doctor_id=?)",Integer.class,id,id,id);}
 public void anonymizeAuditEvents(long userId){db.update("UPDATE audit_event SET actor_user_id=NULL WHERE actor_user_id=?",userId);}
 public void deleteNotifications(long userId){db.update("DELETE FROM notification WHERE user_id=?",userId);}
 public void deleteDoctor(long id){db.update("DELETE FROM doctor WHERE id=?",id);} public void deleteUser(long id){db.update("DELETE FROM app_user WHERE id=? AND role='DOCTOR'",id);}
 public Map<String,Object> doctor(long id){return db.queryForMap("SELECT d.id,d.user_id,d.display_name full_name,u.email,d.registration_id,d.specialty_id,d.department,d.active FROM doctor d LEFT JOIN app_user u ON u.id=d.user_id WHERE d.id=?",id);}
 public Map<String,Object> mine(long u){return db.queryForMap("SELECT d.id,d.user_id,d.display_name full_name,u.email,d.registration_id,d.specialty_id,d.department,d.active FROM doctor d JOIN app_user u ON u.id=d.user_id WHERE d.user_id=?",u);}
 public int branchExists(long id){return db.queryForObject("SELECT COUNT(*) FROM branch WHERE id=? AND active=1",Integer.class,id);}
 public int overlap(long d,LocalDate date,LocalTime s,LocalTime e){return db.queryForObject("SELECT COUNT(*) FROM schedule_template WHERE doctor_id=? AND schedule_date=? AND active=1 AND start_time<CAST(? AS time) AND end_time>CAST(? AS time)",Integer.class,d,date,e.toString(),s.toString());}
 public int overlapExcept(long d,long x,LocalDate date,LocalTime s,LocalTime e){return db.queryForObject("SELECT COUNT(*) FROM schedule_template WHERE doctor_id=? AND id<>? AND schedule_date=? AND active=1 AND start_time<CAST(? AS time) AND end_time>CAST(? AS time)",Integer.class,d,x,date,e.toString(),s.toString());}
 public int roomOverlap(long d,long b,String room,LocalDate date,LocalTime s,LocalTime e,long x){if(room==null||room.isBlank())return 0;return db.queryForObject("SELECT COUNT(*) FROM schedule_template t JOIN doctor_branch db ON db.doctor_id=t.doctor_id AND db.branch_id=t.branch_id WHERE t.doctor_id<>? AND t.id<>? AND t.branch_id=? AND db.room=? AND t.schedule_date=? AND t.active=1 AND t.start_time<CAST(? AS time) AND t.end_time>CAST(? AS time)",Integer.class,d,x,b,room,date,e.toString(),s.toString());}
 public long addSchedule(long d,long b,LocalDate date,LocalTime s,LocalTime e,int m,int c){return db.queryForObject("INSERT INTO schedule_template(doctor_id,branch_id,day_of_week,schedule_date,start_time,end_time,slot_minutes,capacity) OUTPUT INSERTED.id VALUES(?,?,?,?,CAST(? AS time),CAST(? AS time),?,?)",Long.class,d,b,date.getDayOfWeek().getValue(),date,s.toString(),e.toString(),m,c);}
 public void updateSchedule(long id,long b,LocalDate date,LocalTime s,LocalTime e,int m,int c){db.update("UPDATE schedule_template SET branch_id=?,day_of_week=?,schedule_date=?,start_time=CAST(? AS time),end_time=CAST(? AS time),slot_minutes=?,capacity=? WHERE id=?",b,date.getDayOfWeek().getValue(),date,s.toString(),e.toString(),m,c,id);}
 public void disableSchedule(long id){db.update("UPDATE schedule_template SET active=0 WHERE id=?",id);}
 public void retireFutureSlots(long d,long b,LocalDate date,LocalTime s,LocalTime e){db.update("UPDATE slot SET retired=1,status=CASE WHEN status='AVAILABLE' THEN 'BLOCKED' ELSE status END WHERE doctor_id=? AND branch_id=? AND CAST(starts_at AS date)=? AND starts_at>SYSDATETIME() AND CAST(starts_at AS time)>=CAST(? AS time) AND CAST(starts_at AS time)<CAST(? AS time)",d,b,date,s.toString(),e.toString());}
 public List<Map<String,Object>> activeSchedules(){return db.queryForList("SELECT doctor_id,branch_id,schedule_date,start_time,end_time,slot_minutes,capacity FROM schedule_template WHERE active=1 AND schedule_date IS NOT NULL AND schedule_date>=CAST(SYSDATETIME() AS date)");}
 public void createSlot(long d,long b,LocalDateTime s,LocalDateTime e){db.update("IF NOT EXISTS(SELECT 1 FROM slot WHERE doctor_id=? AND status='BOOKED' AND starts_at<? AND ends_at>?) BEGIN UPDATE slot SET ends_at=?,status='AVAILABLE',retired=0,branch_id=? WHERE doctor_id=? AND starts_at=? AND status='BLOCKED'; IF @@ROWCOUNT=0 AND NOT EXISTS(SELECT 1 FROM slot WHERE doctor_id=? AND starts_at=?) INSERT INTO slot(doctor_id,branch_id,starts_at,ends_at) VALUES(?,?,?,?) END",d,e,s,e,b,d,s,d,s,d,b,s,e);}
}

